function result=m2_test_foc_unit
root=fileparts(fileparts(mfilename('fullpath')));folder=fullfile(root,'docs/reports/m2_foc_fixed_point');runtime=fullfile(root,'.runtime/m2_20261024');addpath(fullfile(root,'simulink模型'));[modelFolder,modelCleanup]=m2_test_model_files; m2_test_foc_types;cfg=evalin('base','FOC_Fixed_Config');m='PMLSM_FOC_FixedPoint';load_system(fullfile(modelFolder,[m '.slx']));assert(strcmp(get_param(m,'DataTypeOverride'),'Off'));
set_param(m,'IntegerOverflowMsg','error','IntegerSaturationMsg','error','ParameterOverflowMsg','error','FixptConstOverflowMsg','error','MinMaxOverflowLogging','MinMaxAndOverflow');
feval(m,[],[],[],'compile');b=find_system([m '/FOC_DUT'],'LookUnderMasks','all','FollowLinks','on','MatchFilter',@Simulink.match.activeVariants,'Type','Block');rows=cell(0,4);for k=1:numel(b),t=get_param(b{k},'CompiledPortDataTypes');for key={'Inport','Outport'},if isfield(t,key{1}),v=t.(key{1});for j=1:numel(v),rows(end+1,:)={strrep(b{k},newline,' '),key{1},j,v{j}};assert(~ismember(v{j},{'double','single','half'}),'M2:FLOATING_PATH','%s',b{k});end;end;end;end;feval(m,[],[],[],'term');writetable(cell2table(rows,'VariableNames',{'block','direction','port','compiled_type'}),fullfile(folder,'compiled_types.csv'),'QuoteStrings',true);
reference=m2_make_source_reference(modelFolder);sourceCleanup=onCleanup(@()close_system(reference,0));u=m2_foc_vectors;assert(all(abs(u(:,1:3))<=2,'all')&&all(abs(u(:,6:7))<=2,'all'),'M2:VECTOR_ENVELOPE','随机向量超出首版范围，应保持证据并修正生成器。');
ref=m2_run_foc_sequence(reference,u,false);decoded=u;keys={'Current','Current','Current','Angle','Omega','Current','Current','Reset','Bus'};for j=[1:7 9],decoded(:,j)=double(fi(u(:,j),cfg.Types.(keys{j}),cfg.Fimath));end
refDecoded=m2_run_foc_sequence(reference,decoded,false);fixed=m2_run_foc_sequence(m,u,true);save(fullfile(runtime,'D_unit_raw.mat'),'u','ref','refDecoded','fixed','-v7.3');
metrics=cell(0,7);pass=true;
for name={'duty_u','duty_v','duty_w','vd','vq','x_d','x_q','du_d_z','du_q_z','vd_raw','vq_raw','park_d','park_q'}
 n=name{1};x=fixed.logsout.get(n).Values;a=ref.logsout.get(n).Values;b=refDecoded.logsout.get(n).Values;assert(isequal(x.Time,a.Time));d=double(x.Data(:))-double(a.Data(:));di=double(b.Data(:))-double(a.Data(:));internal=double(x.Data(:))-double(b.Data(:));maximum=max(abs(d));rmse=sqrt(mean(d.^2));lim=Inf;rmsLim=Inf;if startsWith(n,'duty'),lim=1e-4;rmsLim=2e-5;elseif any(strcmp(n,{'vd','vq'})),lim=.01;rmsLim=.002;end;ok=maximum<=lim&&rmse<=rmsLim;pass=pass&&ok;metrics(end+1,:)={n,maximum,rmse,max(abs(di)),max(abs(internal)),lim,ok}; %#ok<AGROW>
end
names=getElementNames(fixed.logsout);for j=1:numel(names),v=fixed.logsout.get(names{j}).Values;assert(all(isfinite(double(v.Data(:)))));if startsWith(names{j},'duty'),assert(all(v.Data>=0&v.Data<=1));end;end
% Actual old-state PI and previous raw-minus-limited AW, with reset priority.
q=@(x)double(fi(x,cfg.Types.Work,cfg.Fimath));pkd=double(fixed.logsout.get('park_d').Values.Data);pkq=double(fixed.logsout.get('park_q').Values.Data);stateErrors=zeros(2,2);
for axis=1:2,if axis==1,st='x_d';aw='du_d_z';raw='vd_raw';limited='vd';error=decoded(:,7)-pkd;else,st='x_q';aw='du_q_z';raw='vq_raw';limited='vq';error=decoded(:,6)-pkq;end
 x=double(fixed.logsout.get(st).Values.Data);a=double(fixed.logsout.get(aw).Values.Data);rv=double(fixed.logsout.get(raw).Values.Data);lv=double(fixed.logsout.get(limited).Values.Data);gain=cfg.Coefficients.Kaw_d.quantized;if axis==2,gain=cfg.Coefficients.Kaw_q.quantized;end;next=q(x+q(cfg.Coefficients.KiTs.quantized*q(error))-q(gain*a));next(decoded(:,8)~=0)=0;awNext=q(rv-lv);stateErrors(axis,:)=[max(abs(x(2:end)-next(1:end-1))) max(abs(a(2:end)-awNext(1:end-1)))];assert(all(stateErrors(axis,:)<=1e-10));end
sectorFixed=double(fixed.logsout.get('sector').Values.Data);sectorReference=double(ref.logsout.get('sector').Values.Data);sectorDifferences=sum(sectorFixed~=sectorReference);
% Negative contract vectors fail before quantization; no silent input clamp.
negativeCases={'nonfinite','bus_zero','current_overrange'};for j=1:3,bad=u(1:3,:);if j==1,bad(2,1)=NaN;elseif j==2,bad(2,9)=0;else,bad(2,1)=3;end;rejected=false;try,m2_run_foc_sequence(m,bad,true);catch exception,rejected=startsWith(exception.identifier,'M2:');end;assert(rejected);end
writetable(cell2table(metrics,'VariableNames',{'signal','total_max_abs','total_rmse','input_quantization_max','internal_plus_coefficient_max','max_budget','pass'}),fullfile(folder,'unit_metrics.csv'));
result=struct('pass',pass,'version',version,'samples',size(u,1),'seed',20261024,'floating_numeric_ports',0,'DataTypeOverride','Off','wrap_and_saturation_diagnostic','error','unexpected_numeric_overflow_or_saturation',0,'all_logged_branches_finite',true,'same_timestamp',true,'state_recursion_max_V',stateErrors,'sector_differences',sectorDifferences,'negative_inputs_rejected',{negativeCases});fid=fopen(fullfile(folder,'unit_acceptance.json'),'w');fprintf(fid,'%s',jsonencode(result,PrettyPrint=true));fclose(fid);assert(pass,'M2:UNIT_BUDGET','量化误差超出冻结预算，见unit_metrics.csv。');fprintf('M2_UNIT_PASS\n');
end
